def gen(rng):
    def fmt(wt, w):
        return f"{len(w)} {wt}\n" + ' '.join(map(str, w))
    tests = [fmt(10, [3, 7, 5, 5, 5]), fmt(8, [4, 4, 4, 4]), fmt(100, [1, 2, 3]), fmt(2, [1]), fmt(2, [1, 1]), fmt(3, [1, 1])]
    for n in (2, 3, 4, 5, 6, 8, 10, 14):
        for _ in range(2):
            tests.append(fmt(rng.randint(2, 12), [rng.randint(1, 6) for _ in range(n)]))
    N = 2 * 10**5
    tests.append(fmt(10**9, [5 * 10**8] * N))
    tests.append(fmt(1000, [rng.randint(1, 1000) for _ in range(N)]))
    tests.append(fmt(2 * 10**9, [10**9] * N))
    a = [rng.randint(10, 10**9) for _ in range(N // 2)]
    S = 10**9 + 7
    tests.append(fmt(S, a + [S - x if S - x >= 1 else 1 for x in a]))
    tests.append(fmt(10**9, [rng.randint(1, 3) * 100 for _ in range(N)]))
    return tests
